import { createHash } from "node:crypto";

/**
 * Minimal OVH API client (signed requests). OVH uses AK/AS/CK triple auth with a
 * SHA1 request signature. Endpoints differ per region.
 */
const ENDPOINTS: Record<string, string> = {
  "ovh-eu": "https://eu.api.ovh.com/1.0",
  "ovh-ca": "https://ca.api.ovh.com/1.0",
  "ovh-us": "https://api.us.ovhcloud.com/1.0",
};

export function ovhConfigured(): boolean {
  return !!(
    process.env.OVH_APPLICATION_KEY &&
    process.env.OVH_APPLICATION_SECRET &&
    process.env.OVH_CONSUMER_KEY
  );
}

function base(): string {
  return ENDPOINTS[process.env.OVH_ENDPOINT ?? "ovh-ca"] ?? ENDPOINTS["ovh-ca"];
}

/** OVH server time (used to avoid clock-skew signature failures). */
async function ovhTime(): Promise<number> {
  const res = await fetch(`${base()}/auth/time`, { signal: AbortSignal.timeout(15_000) });
  return Number(await res.text());
}

export async function ovh(
  method: "GET" | "POST" | "PUT" | "DELETE",
  path: string,
  body?: unknown
): Promise<any> {
  if (!ovhConfigured()) throw new Error("OVH API is not configured");
  const AK = process.env.OVH_APPLICATION_KEY!;
  const AS = process.env.OVH_APPLICATION_SECRET!;
  const CK = process.env.OVH_CONSUMER_KEY!;
  const url = `${base()}${path}`;
  const bodyStr = body !== undefined ? JSON.stringify(body) : "";
  const ts = await ovhTime();
  const toSign = `${AS}+${CK}+${method}+${url}+${bodyStr}+${ts}`;
  const sig = "$1$" + createHash("sha1").update(toSign).digest("hex");

  const res = await fetch(url, {
    method,
    headers: {
      "X-Ovh-Application": AK,
      "X-Ovh-Consumer": CK,
      "X-Ovh-Timestamp": String(ts),
      "X-Ovh-Signature": sig,
      "Content-Type": "application/json",
    },
    body: bodyStr || undefined,
    signal: AbortSignal.timeout(30_000),
  });
  const text = await res.text();
  let json: any = null;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  if (!res.ok) {
    const msg = json?.message ?? text ?? `HTTP ${res.status}`;
    throw new Error(`OVH ${method} ${path} -> ${res.status}: ${msg}`);
  }
  return json;
}

// ---- Convenience wrappers for dedicated IPs / Virtual MACs / reverse DNS ----

export const ovhApi = {
  me: () => ovh("GET", "/me"),
  servers: () => ovh("GET", "/dedicated/server") as Promise<string[]>,
  server: (name: string) => ovh("GET", `/dedicated/server/${name}`),
  ips: () => ovh("GET", "/ip") as Promise<string[]>,
  ipInfo: (ip: string) => ovh("GET", `/ip/${encodeURIComponent(ip)}`),
  /** Virtual MACs registered on a dedicated server. */
  virtualMacs: (server: string) => ovh("GET", `/dedicated/server/${server}/virtualMac`),
  /** Create a Virtual MAC for an additional IP so it can be routed to a VM. */
  createVirtualMac: (server: string, ipAddress: string, name: string) =>
    ovh("POST", `/dedicated/server/${server}/virtualMac`, {
      ipAddress,
      type: "ovh",
      virtualMachineName: name,
    }),
  /** Set reverse DNS (PTR) for an IP. */
  setReverse: (ipBlock: string, ip: string, reverse: string) =>
    ovh("POST", `/ip/${encodeURIComponent(ipBlock)}/reverse`, { ipReverse: ip, reverse }),
};
