 * line (79 ⇄ 81) would flap open/closed every sweep and bury the operator in
 * churn. Env-overridable for tuning without a redeploy.
 */
export const NODE_CAP_RESOLVE_MARGIN = Number(process.env.NXEON_NODE_ALERT_RESOLVE_MARGIN ?? 5);

/**
 * A persistent (unchanged-severity) condition re-notifies at most once per this
 * many hours — the debounce that stops "node stuck at 92%" emailing ops every
 * 10-minute sweep. A NEW alert and a WARN⇄CRITICAL change always notify
 * immediately regardless of the cooldown.
 */
export const NODE_CAP_COOLDOWN_HOURS = Number(process.env.NXEON_NODE_ALERT_COOLDOWN_HOURS ?? 6);

/**
 * Every server status EXCEPT DELETING still holds committed capacity on its node
 * — its VM (and its RAM/disk reservation) exists until the delete completes. This
 * matches the exclusion the existing scheduler and infra pages already use
 * (`status: { not: "DELETING" }`), so the utilization shown here agrees with what
 * scheduleNode commits against.
 */
