 * both in 1..100, and CRITICAL never below WARN (a CRITICAL under WARN would make
 * the amber band unreachable and every warn instantly read critical).
 */
export async function nodeThresholds(): Promise<NodeThresholds> {
  let warnPct = await getSettingInt("node_warn_pct", NODE_CAP_DEFAULT_WARN);
  let critPct = await getSettingInt("node_critical_pct", NODE_CAP_DEFAULT_CRIT);
