  const promo = currentPromo(new Date());

  // "From" price anchor — cheapest active hosting plan, read live from the DB
  // (the same figure checkout charges); null when no plan exists so we never
  // invent a number.
  const fromCents = plans.length ? Math.min(...plans.map((p) => p.priceCents)) : null;

  // Highlight the featured tier (or the middle one) with the site's popular
  // treatment so the smart buy reads clearly.
  const featuredIdx = plans.findIndex((p) => p.featured);
  const popularIdx = featuredIdx >= 0 ? featuredIdx : plans.length >= 3 ? Math.floor((plans.length - 1) / 2) : -1;

  return (
    <div className="relative min-h-screen overflow-hidden">
      <FaqJsonLd items={HOSTING_FAQ} />
      {plans.length > 0 && (
        <ProductOffersJsonLd
