      {/* Ambient dot-field + soft aura for depth — the sitewide v5 signature. */}
      <div aria-hidden className="pointer-events-none absolute inset-0 z-0">
        <AmbientField />
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_70%_50%_at_20%_-5%,rgba(111,71,245,0.10),transparent_60%),radial-gradient(ellipse_60%_40%_at_90%_0%,rgba(59,130,246,0.08),transparent_60%)]" />
      </div>

      <div className="relative z-10">
        <PageHero
          eyebrow="Web Hosting"
          title="Get your website online"
          highlight="without managing a server"
          sub="We run PHP, databases, email and SSL for you. Point your domain at us and you're live — with free migration from your current host."
          primary={{ label: "Get started", href: "/dashboard/hosting" }}
          secondary={{ label: "See plans", href: "#plans" }}
        >
          <div className="mt-8 flex flex-col items-center gap-5">
            {fromCents != null && (
              <div className="flex flex-wrap items-center justify-center gap-3">
                <span className="inline-flex items-center gap-2 rounded-full border border-brand-500/30 bg-brand-500/[0.08] px-4 py-1.5 text-sm">
                  <span className="text-slate-400">Plans from</span>
                  <span className="font-bold text-white">{money(fromCents)}/mo</span>
                  <span className="text-slate-500">·</span>
                  <span className="font-semibold text-emerald-300">first month free</span>
                </span>
              </div>
            )}
            <div className="flex justify-center">
              <TrustBadges items={["Free SSL", "Free migration", "No setup fees", "Cancel anytime"]} />
            </div>
            <ReviewBadges />
            <Link href="/migrate" className="inline-flex items-center gap-1.5 text-sm text-slate-400 transition-colors hover:text-brand-200">
              Already have a site? Migrate my site free
              <IconArrow size={14} />
            </Link>
          </div>
        </PageHero>

        {/* Plans — surfaced high so price + CTA are visible early on a paid lander */}
        <Section tone="panel" size="lg" id="plans">
          <SectionTitle
            eyebrow="Pricing"
            title="Simple monthly plans"
            sub="No setup fees. Cancel anytime. Free migration from your current host."
          />
